import React from 'react';
import './App.css';
import Header from './Component/Header';
import Sidebar from './Component/Sidebar';
import VideoGrid from './Component/VideoGrid';
import Shorts from './Component/Shorts'



function App() {
  return (
    <div className="app">
      <Header />
      <div className="app__body">
        <Sidebar />
        
        <VideoGrid />
        <Shorts />
      </div>
    </div>
  );
}

export default App;
